package app.materialclock.data import android.content.Context import androidx.datastore.preferences.core.booleanPreferencesKey import androidx.datastore.preferences.core.edit import androidx.datastore.preferences.core.floatPreferencesKey import androidx.datastore.preferences.core.intPreferencesKey import androidx.datastore.preferences.core.stringPreferencesKey import androidx.datastore.preferences.preferencesDataStore import kotlinx.coroutines.flow.Flow import kotlinx.coroutines.flow.map private val Context.dataStore by preferencesDataStore(name = "clock_settings") class ClockStore(private val context: Context) { companion object { private val DYNAMIC_COLORS = booleanPreferencesKey("dynamic_colors") private val CUSTOM_ACCENT_HEX = stringPreferencesKey("custom_accent_hex") private val FROSTED_GLASS = booleanPreferencesKey("frosted_glass") private val ONE_HANDED_MODE = booleanPreferencesKey("one_handed_mode") private val DEFAULT_ALARM_URI = stringPreferencesKey("default_alarm_uri") private val ALARM_VOLUME = floatPreferencesKey("alarm_volume") private val FOCUS_MODE_DURATION = intPreferencesKey("focus_mode_duration") private val GRADUAL_VOLUME = booleanPreferencesKey("gradual_volume") } val settingsFlow: Flow<Settings> = context.dataStore.data.map { prefs -> Settings( dynamicColors = prefs[DYNAMIC_COLORS] ?: true, customAccentHex = prefs[CUSTOM_ACCENT_HEX] ?: "#6750A4", enableFrostedGlass = prefs[FROSTED_GLASS] ?: false, enableOneHandedMode = prefs[ONE_HANDED_MODE] ?: true, defaultAlarmUri = prefs[DEFAULT_ALARM_URI] ?: "", alarmVolume = prefs[ALARM_VOLUME] ?: 0.8f, focusModeDurationMinutes = prefs[FOCUS_MODE_DURATION] ?: 25, enableGradualVolume = prefs[GRADUAL_VOLUME] ?: true ) } suspend fun updateSettings(newSettings: Settings) { context.dataStore.edit { prefs -> prefs[DYNAMIC_COLORS] = newSettings.dynamicColors prefs[CUSTOM_ACCENT_HEX] = newSettings.customAccentHex prefs[FROSTED_GLASS] = newSettings.enableFrostedGlass prefs[ONE_HANDED_MODE] = newSettings.enableOneHandedMode prefs[DEFAULT_ALARM_URI] = newSettings.defaultAlarmUri prefs[ALARM_VOLUME] = newSettings.alarmVolume prefs[FOCUS_MODE_DURATION] = newSettings.focusModeDurationMinutes prefs[GRADUAL_VOLUME] = newSettings.enableGradualVolume } } } 
